#include "ed_internal.h"
#include <immintrin.h>
static uint32_t od(uint32_t n,uint32_t k,uint32_t s,uint32_t p){return(n+2u*p-k)/s+1u;}
static float hsum(__m256 v){__m128 lo=_mm256_castps256_ps128(v),hi=_mm256_extractf128_ps(v,1);lo=_mm_add_ps(lo,hi);lo=_mm_hadd_ps(lo,lo);lo=_mm_hadd_ps(lo,lo);return _mm_cvtss_f32(lo);}
void ed_conv2d_f32_avx2_range(const float*in,uint32_t ih,uint32_t iw,uint32_t ic,const float*w,const float*b,uint32_t oc,uint32_t k,uint32_t s,uint32_t p,float*out,size_t begin,size_t end){uint32_t ow=od(iw,k,s,p);size_t site;for(site=begin;site<end;++site){uint32_t y=(uint32_t)(site/ow),x=(uint32_t)(site%ow),o,ky,kx;for(o=0;o<oc;++o){__m256 sum=_mm256_setzero_ps();float tail=b?b[o]:0.0f;for(ky=0;ky<k;++ky){int iy=(int)(y*s+ky)-(int)p;if(iy<0||iy>=(int)ih)continue;for(kx=0;kx<k;++kx){int ix=(int)(x*s+kx)-(int)p;uint32_t c=0;if(ix<0||ix>=(int)iw)continue;{const float*q=in+((size_t)(uint32_t)iy*iw+(uint32_t)ix)*ic,*z=w+(((size_t)o*k+ky)*k+kx)*ic;for(;c+8u<=ic;c+=8u)sum=_mm256_fmadd_ps(_mm256_loadu_ps(q+c),_mm256_loadu_ps(z+c),sum);for(;c<ic;++c)tail+=q[c]*z[c];}}}out[site*oc+o]=tail+hsum(sum);}}}
void ed_depthwise_conv2d_f32_avx2_range(const float*in,uint32_t ih,uint32_t iw,uint32_t c,const float*w,const float*b,uint32_t k,uint32_t s,uint32_t p,float*out,size_t begin,size_t end){uint32_t ow=od(iw,k,s,p);size_t site;for(site=begin;site<end;++site){uint32_t y=(uint32_t)(site/ow),x=(uint32_t)(site%ow),ch,ky,kx;float*q=out+site*c;for(ch=0;ch+8u<=c;ch+=8u){__m256 sum=b?_mm256_loadu_ps(b+ch):_mm256_setzero_ps();for(ky=0;ky<k;++ky){int iy=(int)(y*s+ky)-(int)p;if(iy<0||iy>=(int)ih)continue;for(kx=0;kx<k;++kx){int ix=(int)(x*s+kx)-(int)p;if(ix<0||ix>=(int)iw)continue;sum=_mm256_fmadd_ps(_mm256_loadu_ps(in+((size_t)(uint32_t)iy*iw+(uint32_t)ix)*c+ch),_mm256_loadu_ps(w+((size_t)ky*k+kx)*c+ch),sum);}}_mm256_storeu_ps(q+ch,sum);}for(;ch<c;++ch){float sum=b?b[ch]:0.0f;for(ky=0;ky<k;++ky){int iy=(int)(y*s+ky)-(int)p;if(iy<0||iy>=(int)ih)continue;for(kx=0;kx<k;++kx){int ix=(int)(x*s+kx)-(int)p;if(ix>=0&&ix<(int)iw)sum+=in[((size_t)(uint32_t)iy*iw+(uint32_t)ix)*c+ch]*w[((size_t)ky*k+kx)*c+ch];}}q[ch]=sum;}}}
